public void testGetLeads() {
    if (!checkCanRunTests())
        return;
    Set<String> recentLeadIds = sfdcServiceImpl.getRecentLeadIds();
    if (recentLeadIds == null || recentLeadIds.size() == 0) {
        return;
    }
    for (String recentLeadId : recentLeadIds) {
